  "elsewhere": [
    {
      "entry": "Church of the Eternal Light",
      "text": "The Church of the Eternal Light regards the Illumination as the defining event of its theology, central to its Doctrines of divine transformation and the Eternal Light's ongoing relationship with the Tsardom.",
      "held_by": null
    },
    {
      "entry": "Moscavian Owl-folk",
      "text": "The Moscavian Owl-folk who emerged from the Illumination of 994 are the direct descendants of Moscavia's pre-transformation human population, now living as nocturnal, avian beings with preserved human minds.",
      "held_by": null
    },
