  "elsewhere": [
    {
      "entry": "Moscavian Owl-folk",
      "text": "The pure-line Moscavian Owl-folk, those whose bloodline remained unbroken through all four grandparents, emerged from the Illumination as snowy owls—pristine, white-feathered beings that now constitute the majority of the Tsardom's population.",
      "held_by": null
    },
    {
      "entry": "Church of the Eternal Light",
      "text": "The Illumination is enshrined as the defining doctrine of the Church, forming the bedrock of its theology that truth is found through the Light and that darkness represents the absence of divine knowledge.",
      "held_by": "Church of the Eternal Light"
    },
    {
      "entry": "The Eternal Light",
      "text": "The Illumination is understood as the direct act of the Eternal Light itself, the supreme creative force worshipped as the source of all existence in Moscavian faith.",
      "held_by": null
    },
    {
